model.pnc_analytics.int_claims_payments.raw_code:
{{ config(materialized='incremental', unique_key='claim_id') }}

select
    claim_id,
    payment_type,
    count(*)            as payment_count,
    sum(amount_chf)     as paid_chf,
    max(payment_date)   as last_payment_date
from {{ ref('src_claims_payments') }}
{% if is_incremental() %}
where payment_date >= date_sub(current_date(), interval 7 day)
{% endif %}
group by 1, 2
